<!-- Client-side Logic: Switching images, sizes, tabs, and add to cart feedback -->
<script>
    let currentQty = 1;
    let isWishlisted = false;

    function switchImage(index, element) {
      const mainImg = document.getElementById('main-product-image');
      const allThumbs = document.querySelectorAll('.thumb-btn');
      
      allThumbs.forEach(t => {
        t.classList.remove('active', 'opacity-100', 'ring-2', 'ring-primary');
        t.classList.add('opacity-60');
      });

      element.classList.add('active', 'opacity-100', 'ring-2', 'ring-primary');
      element.classList.remove('opacity-60');

      mainImg.style.opacity = '0.3';
      setTimeout(() => {
        // Subtle image switch transition
        mainImg.style.opacity = '1';
      }, 150);
    }

    function selectVariant(type, price, strike, desc, button) {
      document.getElementById('price-display').innerText = price;
      document.getElementById('strike-price').innerText = strike;
      document.getElementById('variant-label').innerText = desc;

      const buttons = document.querySelectorAll('.variant-btn');
      buttons.forEach(btn => {
        btn.classList.remove('active', 'ring-2', 'ring-primary', 'bg-surface-container-lowest');
        btn.classList.add('bg-surface-container-low');
      });

      button.classList.add('active', 'ring-2', 'ring-primary', 'bg-surface-container-lowest');
      button.classList.remove('bg-surface-container-low');
    }

    function adjustQty(delta) {
      const counter = document.getElementById('qty-counter');
      currentQty = Math.max(1, currentQty + delta);
      counter.innerText = currentQty;
    }

    function switchTab(tabId, button) {
      const panels = document.querySelectorAll('.tab-panel');
      const tabs = document.querySelectorAll('.tab-link');

      panels.forEach(p => p.classList.add('hidden'));
      tabs.forEach(t => {
        t.classList.remove('active', 'text-primary', 'font-normal');
        t.classList.add('text-outline-variant', 'font-light');
        const indicator = t.querySelector('.indicator');
        if (indicator) indicator.classList.replace('bg-primary', 'bg-transparent');
      });

      document.getElementById('tab-' + tabId).classList.remove('hidden');
      button.classList.add('active', 'text-primary', 'font-normal');
      button.classList.remove('text-outline-variant', 'font-light');
      const activeIndicator = button.querySelector('.indicator');
      if (activeIndicator) activeIndicator.classList.replace('bg-transparent', 'bg-primary');
    }

    function triggerAddToCart() {
      const btn = document.getElementById('add-to-cart-btn');
      const text = document.getElementById('btn-text');
      
      const originalText = text.innerText;
      text.innerText = "Telah Ditambahkan (" + currentQty + ")";
      btn.classList.add('bg-secondary', 'text-on-secondary');
      btn.classList.remove('bg-primary');

      setTimeout(() => {
        text.innerText = originalText;
        btn.classList.remove('bg-secondary', 'text-on-secondary');
        btn.classList.add('bg-primary');
      }, 1800);
    }

    function toggleWishlist(button) {
      isWishlisted = !isWishlisted;
      const icon = document.getElementById('wishlist-icon');
      if (isWishlisted) {
        icon.style.fontVariationSettings = "'FILL' 1";
        icon.classList.add('text-secondary');
      } else {
        icon.style.fontVariationSettings = "'FILL' 0";
        icon.classList.remove('text-secondary');
      }
    }

    function toggleInciDrawer() {
      const drawer = document.getElementById('inci-drawer');
      drawer.classList.toggle('hidden');
    }
  </script>
